CREATE TABLE `ci_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint unsigned NOT NULL,
  `language_id` bigint unsigned NOT NULL,
  `modality_id` bigint unsigned NOT NULL,
  `input_source_id` bigint unsigned NOT NULL,
  `started_at` datetime NOT NULL,
  `ended_at` datetime DEFAULT NULL,
  `paused_duration_seconds` int unsigned NOT NULL DEFAULT '0',
  `paused_at` datetime DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ci_sessions_language_id_foreign` (`language_id`),
  KEY `ci_sessions_modality_id_foreign` (`modality_id`),
  KEY `ci_sessions_input_source_id_foreign` (`input_source_id`),
  KEY `ci_sessions_user_id_started_at_index` (`user_id`,`started_at`),
  CONSTRAINT `ci_sessions_input_source_id_foreign` FOREIGN KEY (`input_source_id`) REFERENCES `input_sources` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ci_sessions_language_id_foreign` FOREIGN KEY (`language_id`) REFERENCES `languages` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ci_sessions_modality_id_foreign` FOREIGN KEY (`modality_id`) REFERENCES `modalities` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `ci_sessions_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1850 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
